import itertools
import networkx as nx

def is_diverse(S, n):
    # S is a list of tuples (flags)
    # Check for c=0
    G0 = nx.Graph()
    for i, flag in enumerate(S):
        for j in range(n):
            if flag[j] == 0:
                G0.add_edge(f"f{i}", f"j{j}")
    if nx.bipartite.matching.hopcroft_karp_matching(G0, top_nodes=[f"f{i}" for i in range(len(S))]) != {}:
        # Wait, hopcroft_karp returns a dictionary of the matching.
        # The size of the matching is half the length of the dictionary.
        pass

    # Let's use max_weight_matching or simply nx.bipartite.matching.hopcroft_karp_matching
    matching0 = nx.bipartite.matching.hopcroft_karp_matching(G0, top_nodes=[f"f{i}" for i in range(len(S))])
    if len(matching0) // 2 >= n:
        return True

    G1 = nx.Graph()
    for i, flag in enumerate(S):
        for j in range(n):
            if flag[j] == 1:
                G1.add_edge(f"f{i}", f"j{j}")
    matching1 = nx.bipartite.matching.hopcroft_karp_matching(G1, top_nodes=[f"f{i}" for i in range(len(S))])
    if len(matching1) // 2 >= n:
        return True

    return False

def find_M(n):
    import itertools
    all_flags = list(itertools.product([0, 1], repeat=n))
    num_flags = len(all_flags)

    for M in range(1, num_flags + 1):
        # Check if every S of size M is diverse
        # This is too slow for large M, but let's see.
        # We only need to check if THERE EXISTS an S of size M that is NOT diverse.
        # If such S exists, then M is not the answer, M_min > M.
        found_not_diverse = False
        for S in itertools.combinations(all_flags, M):
            if not is_diverse(S, n):
                found_not_diverse = True
                break
        if not found_not_diverse:
            return M
    return None

for n in range(1, 5):
    print(f"n={n}, M={find_M(n)}")

